insert into public.knowledge_sources(id,title,url,kind,locator,accessed_at,notes) values ('original-demo','Original fictional demonstration','https://example.invalid/pinballpilot/demo','original','content/demo-pack.json','2026-10-09','Original software test fixture. These rules do not describe a real pinball machine. Diagram created for this project, CC0.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-ramp-build','workshop-demo','recommendation','Build the ramp bonus','Shoot the left ramp. This qualifies the ramp bonus and gives you a repeatable scoring route.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-ramp-collect','workshop-demo','recommendation','Collect the ramp bonus','Shoot the right ramp. The left ramp has qualified this bonus; the right ramp collects it.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-mode-qualify','workshop-demo','recommendation','Qualify a mode','Shoot the spinner lane. This lights the mode scoop for an advanced scoring sequence.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-mode-start','workshop-demo','recommendation','Start a mode','Shoot the mode scoop. Starting the mode makes the bullseye award available.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-mode-finish','workshop-demo','recommendation','Finish the mode','Shoot the bullseye. With the mode active, this shot collects its scoring award.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-light-lock','workshop-demo','recommendation','Light the lock','Complete the drop-target bank. This lights the ball lock, the first step toward multiball.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-lock-one','workshop-demo','recommendation','Lock the first ball','Shoot the lit ball lock. This records your first lock toward multiball.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-lock-two','workshop-demo','recommendation','Lock the second ball','Shoot the ball lock again. The second lock brings you one step closer.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-lock-three','workshop-demo','recommendation','Start multiball','Shoot the ball lock for the third time. The third lock starts this demonstration machine’s multiball.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-jackpot','workshop-demo','recommendation','Collect a jackpot','Shoot the left orbit. During multiball, the left orbit collects a jackpot.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture; not authentic machine content.') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('claim-guide','workshop-demo','recommendation','Demonstration guide sequences','Fictional demo: use ramp bonus for simple scoring, the spinner/scoop/bullseye sequence for advanced scoring, or drop targets and three locks for multiball.',array['original-demo'],'approved',1,1,'demo-1','Original fictional fixture.') on conflict do nothing;
