insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('trooper-three','iron-maiden-pro','fact','Three Trooper locks start multiball','Collect three qualified locks to begin Trooper Multiball.',array['stern-card'],'pending',1,null,'Unverified — capture the installed version during the next visit','') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('mummy','iron-maiden-pro','fact','Mummy uses the captive ball','The sarcophagus captive ball advances Mummy Multiball. Exact hit counts and the Pro lock sequence still need verification.',array['stern-card'],'pending',1,null,'Unverified — capture the installed version during the next visit','') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('eddie','iron-maiden-pro','fact','Eddie letters lead to modes','Collect EDDIE letters through the main shots, then use the middle shot to begin a mode. Check the lit indicators and display.',array['stern-card'],'pending',1,null,'Unverified — capture the installed version during the next visit','') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('four-flippers','iron-maiden-pro','fact','Pro has four flippers','The Pro playfield has four flippers, including a full-size upper-right flipper.',array['stern-pro'],'pending',1,null,'Unverified — capture the installed version during the next visit','') on conflict do nothing;
insert into public.claims(id,variant_id,kind,title,body,source_ids,status,revision,reviewed_revision,software,review_note) values ('jump-ramp','iron-maiden-pro','fact','Pro centre jump ramp','The Pro has a stainless-steel centre jump ramp and a segmented bullseye target.',array['stern-pro'],'pending',1,null,'Unverified — capture the installed version during the next visit','') on conflict do nothing;
